    tasks:[{id:'TSK-016',title:'Confirm glove sizes for next order',assignee:'Demo Sales',start:'2026-10-26T09:00',end:'2026-10-26T10:00',reminder:'30 minutes before',status:'In progress',priority:'High',channel:'In-app'},{id:'TSK-015',title:'Follow up on quotation QUO-2026-022',assignee:'Demo Manager',start:'2026-10-26T14:00',end:'2026-10-26T14:30',reminder:'1 hour before',status:'Open',priority:'Normal',channel:'Email preview'}],
    leads:[{id:'OPP-008',name:'Metsi clinic group',stage:'Quotation sent',value:7800,owner:'Demo Sales',next:'Review sample quote'},{id:'OPP-007',name:'Northside Medical Centre',stage:'Needs identified',value:5200,owner:'Demo Manager',next:'Schedule product discussion'}],
    appointments:[{id:'MTG-026',title:'Product requirements review',contact:'Metsi Health Clinic',date:'2026-10-28T10:30',owner:'Demo Sales',status:'Scheduled'}],
    shipments:[{id:'SHP-011',order:'INV-2026-040',customer:'Tshiamo Diagnostics',carrier:'Manual status',tracking:'DEMO-TRK-011',date:'2026-10-20',status:'In transit'}],
    documents:[{id:'DOC-013',name:'Sample supplier agreement.pdf',category:'Supplier records',classification:'Confidential',updated:'2026-10-21',owner:'Demo Admin'},{id:'DOC-012',name:'Sample glove specification sheet.pdf',category:'Product records',classification:'Internal',updated:'2026-10-18',owner:'Demo Inventory'}],
    payroll:[{id:'PAY-006',name:'Demo Team Member A',period:'Oct 2026',gross:12400,status:'Draft preview'},{id:'PAY-005',name:'Demo Team Member B',period:'Oct 2026',gross:9800,status:'Draft preview'}],
    activity:[{at:'Today · 09:42',text:'Sample payment recorded against INV-2026-041',type:'Finance'},{at:'Today · 09:18',text:'Task assigned to Demo Sales',type:'Team'},{at:'Yesterday · 16:06',text:'Sample quote QUO-2026-022 prepared',type:'Sales'},{at:'Yesterday · 11:32',text:'Stock reorder point reached for latex gloves',type:'Stock'}],
    notifications:[{title:'Low stock · Latex gloves',detail:'Below the sample reorder point',when:'Today · 08:30',read:false},{title:'Task due today',detail:'Confirm glove sizes for next order',when:'Today · 08:00',read:false},{title:'Sample invoice reminder',detail:'INV-2026-039 · Metsi Health Clinic',when:'Yesterday',read:true}],
